"use strict";const e=require("./request.js");exports.createRoom=function(o){return e.post("/rooms",o)},exports.deleteRoom=function(o){return e.del(`/rooms/${o}`)},exports.getMembers=function(o){return e.get(`/rooms/${o}/members`)},exports.getMyRooms=function(){return e.get("/rooms")},exports.getRoomDetail=function(o){return e.get(`/rooms/${o}`)},exports.joinRoom=function(o,r){return e.post(`/rooms/${o}/join`,{invite_code:r})},exports.leaveRoom=function(o){return e.post(`/rooms/${o}/members/leave`)},exports.removeMember=function(o,r){return e.del(`/rooms/${o}/members/${r}`)},exports.transferOwnership=function(o,r){return e.post(`/rooms/${o}/transfer`,{target_user_id:r})};
